def predict(board, action):
    mouse_row, mouse_col = action[1], action[2]
    mouse_char = board[mouse_row][mouse_col]

    if mouse_char == 'B':
        for i in range(max(0, mouse_row-1), min(64, mouse_row+2)):
            for j in range(max(0, mouse_col-1), min(64, mouse_col+2)):
                if board[i][j] == 'N':
                    board[i][j] = 'S'
        board[mouse_row][mouse_col] = 'S'
    elif mouse_char == 'G':
        for i in range(max(0, mouse_row-1), min(64, mouse_row+2)):
            for j in range(max(0, mouse_col-1), min(64, mouse_col+2)):
                if board[i][j] == 'N':
                    board[i][j] = 'G'
        board[mouse_row][mouse_col] = 'S'
    else:
        board[mouse_row][mouse_col] = 'p'

    return [''.join(row) for row in board]
